'info-panel': {
  url: b => b + '/files',
  setup: async page => {
    await page.waitForSelector('main', { timeout: 15000 });
    await page.waitForTimeout(1200);
    await page.locator('button.action[aria-label*="Info"], button.action[aria-label*="info"]').first().click();
    await page.waitForSelector('.card.floating, #modal-background', { state: 'visible', timeout: 10000 });
    await page.waitForTimeout(600);
  },
},
'multiple-select': {
  url: b => b + '/files',
  setup: async page => {
    await page.waitForSelector('main', { timeout: 15000 });
    await page.waitForTimeout(1200);
    await page.locator('button.action[aria-label*="select multiple"], button.action[aria-label*="Select multiple"]').first().click();
    await page.waitForSelector('#multiple-selection.active, .item input[type="checkbox"]', { state: 'visible', timeout: 10000 });
    await page.waitForTimeout(600);
  },
},
'mobile-drawer': {
  url: b => b + '/files',
  setup: async page => {
    await page.setViewportSize({ width: 700, height: 800 });
    await page.waitForSelector('main', { timeout: 15000 });
    await page.waitForTimeout(1200);
    await page.locator('.menu-button').first().click();
    await page.waitForSelector('nav.active, #nav.active, #nav, .overlay', { state: 'visible', timeout: 10000 });
    await page.waitForTimeout(600);
  },
},
